{
  "assessment": "The source packet is a single LaTeX manuscript (arXiv 2507.00684v1) describing an experimental study of bidisperse granular silo discharge. The selected quantitative cluster is the correlation between the time-averaged hexatic order parameter <|psi_6|>_t and the kinematic diffusion length b, with the reported linear fit b/d = 4.8 * <|psi_6|>_t (r=0.942) over y/d in [10,70]. The controls are the mass fraction f and height y/d; the readouts are b/d and <|psi_6|>_t. The source reports a single linear fit with slope 4.8 and correlation coefficient 0.942, but does not provide an intercept or uncertainty on the slope. The domain for f is reported as discrete values (0, 0.05, 0.1, 0.2, 0.5, 1) and for y/d as a continuous interval [10,70] for the correlation. The case is authoring-ready because there is at least one numeric control (f, y/d), one numeric readout (b/d), a quantitative mechanism (kinematic model and linear correlation), and an objective source-grounded response within an explicit domain.",
  "case_authoring_ready": true,
  "source": {
    "citation": "David Luce, Correlation between Structural Order and Diffusion Length in Granular Flow, Physical Review Letters (2026), DOI:10.1103/7mcs-xyzs",
    "journal_doi": "10.1103/7mcs-xyzs",
    "arxiv_versioned_id": "2507.00684v1"
  },
  "paper_scope": "Experimental study of bidisperse granular discharge from a quasi-2D silo, investigating how structural order (crystallization) affects the diffusion length b in the kinematic model. The paper reports a strong correlation between b and the time-averaged hexatic order parameter <|psi_6|>_t, with a linear fit slope 4.8 and correlation coefficient 0.942 over y/d in [10,70].",
  "mechanisms": [
    {
      "mechanism_id": "kinematic_model",
      "statement": "The vertical velocity profile in the silo is described by the kinematic model of Nedderman and Tüzün, v_y(x,y) = Q / sqrt(4*pi*b*y) * exp(-x^2/(4*b*y)), where b is a characteristic diffusion length and Q is the time-averaged flow rate.",
      "equations": [
        "v_y(x,y) = Q / sqrt(4*pi*b*y) * exp(-x^2/(4*b*y))"
      ],
      "variable_names": [
        "v_y",
        "x",
        "y",
        "Q",
        "b"
      ],
      "parameters": [
        {
          "name": "kinematic_model_pi",
          "value": 3.141592653589793,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "Mathematical constant pi in the kinematic model equation.",
          "anchors": [
            {
              "line_start": 85,
              "line_end": 88,
              "support": "Equation (Eq:kinematic_model) includes the factor 1/sqrt(4*pi*b*y)."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 84,
          "line_end": 89,
          "support": "The kinematic model is introduced and the equation v_y = Q/sqrt(4*pi*b*y)*exp(-x^2/(4*b*y)) is given, with b as a single fitting parameter."
        }
      ]
    },
    {
      "mechanism_id": "hexatic_order_parameter",
      "statement": "The local hexatic order parameter for each particle k is defined as psi_6k = (1/N_k) * sum_{l=1}^{N_k} exp(i*6*theta_{kl}), where N_k is the number of nearest neighbors and theta_{kl} are angular positions. The time-averaged magnitude <|psi_6|>_t is used as an Eulerian field.",
      "equations": [
        "psi_6k = (1/N_k) * sum_{l=1}^{N_k} exp(i*6*theta_{kl})"
      ],
      "variable_names": [
        "psi_6k",
        "N_k",
        "theta_kl"
      ],
      "parameters": [],
      "anchors": [
        {
          "line_start": 50,
          "line_end": 55,
          "support": "Definition of psi_6k and its interpretation as a measure of sixfold symmetry."
        },
        {
          "line_start": 106,
          "line_end": 108,
          "support": "The time-averaged field <|psi_6|>_t is computed and related to plastic rearrangements."
        }
      ]
    },
    {
      "mechanism_id": "b_psi6_correlation",
      "statement": "The diffusion length b is linearly correlated with the time-averaged hexatic order parameter <|psi_6|>_t, with a slope of 4.8 and correlation coefficient r=0.942 over the range y/d in [10,70].",
      "equations": [
        "b/d = 4.8 * <|psi_6|>_t"
      ],
      "variable_names": [
        "b",
        "psi_6"
      ],
      "parameters": [
        {
          "name": "b_psi6_correlation_slope",
          "value": 4.8,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "Slope of the linear correlation between b/d and <|psi_6|>_t.",
          "anchors": [
            {
              "line_start": 115,
              "line_end": 115,
              "support": "Caption states 'The black line corresponds to a line with slope 4.8.'"
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 115,
          "line_end": 115,
          "support": "Caption reports correlation r=0.942 and slope 4.8 for the line in the figure."
        }
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "silo_geometry",
      "statement": "Quasi-2D flat-bottomed silo with height H=300 mm, width L=100 mm, depth W=1.25 mm, and outlet width 18 mm.",
      "anchors": [
        {
          "line_start": 47,
          "line_end": 47,
          "support": "Cell dimensions and outlet width are given."
        }
      ]
    },
    {
      "condition_id": "particle_sizes",
      "statement": "Binary mixture of steel spheres with diameters d1=1.0 mm and d2=1.2 mm, average reference diameter d=1.1 mm.",
      "anchors": [
        {
          "line_start": 47,
          "line_end": 47,
          "support": "Particle diameters and average diameter are specified."
        }
      ]
    },
    {
      "condition_id": "imaging_setup",
      "statement": "High-speed camera at 2000 frames per second, resolution 1024x1024 pixels covering approximately 91d x 91d area, focusing on bottom region during steady-state discharge.",
      "anchors": [
        {
          "line_start": 47,
          "line_end": 47,
          "support": "Recording details are provided."
        }
      ]
    },
    {
      "condition_id": "eulerian_grid",
      "statement": "Eulerian grid with square cells of size d x d, bottom-central cell aligned with silo outlet center.",
      "anchors": [
        {
          "line_start": 47,
          "line_end": 47,
          "support": "Grid construction is described."
        }
      ]
    },
    {
      "condition_id": "plug_flow_removed",
      "statement": "For fitting the kinematic model, the plug flow component is removed from the velocity profiles.",
      "anchors": [
        {
          "line_start": 91,
          "line_end": 91,
          "support": "Text states 'Removing the plug flow component, the Gaussian-like shape can still be fitted using the kinematic model.'"
        }
      ]
    }
  ],
  "controls": [
    {
      "name": "mass_fraction_f",
      "definition": "Mass fraction of small beads (diameter 1.0 mm) in the binary mixture.",
      "unit": "dimensionless",
      "domain_kind": "numeric_values",
      "minimum": null,
      "maximum": null,
      "allowed_values": [0, 0.05, 0.1, 0.2, 0.5, 1],
      "domain_statement": "The paper reports experiments at f=0, 0.05, 0.1, 0.2, 0.5, and 1 (see snapshots and figures).",
      "anchors": [
        {
          "line_start": 41,
          "line_end": 41,
          "support": "Snapshots for f=0, 0.05, 0.1, 0.2 are shown."
        },
        {
          "line_start": 57,
          "line_end": 57,
          "support": "PDFs for various f, including f=0.5 and f=1, are discussed."
        }
      ]
    },
    {
      "name": "height_y_over_d",
      "definition": "Vertical position in the silo normalized by the average particle diameter d.",
      "unit": "dimensionless",
      "domain_kind": "continuous_interval",
      "minimum": 10,
      "maximum": 70,
      "allowed_values": [],
      "domain_statement": "The correlation between b and <|psi_6|>_t is reported in the range y/d in [10,70].",
      "anchors": [
        {
          "line_start": 115,
          "line_end": 115,
          "support": "Caption states 'in the range y/d in [10,70]'."
        }
      ]
    }
  ],
  "readouts": [
    {
      "name": "diffusion_length_b_over_d",
      "definition": "Characteristic diffusion length b extracted from fitting the kinematic model to vertical velocity profiles, normalized by the average particle diameter d.",
      "unit": "dimensionless",
      "statistic": "Fitted parameter from velocity profiles; values reported as a function of height and mixing fraction.",
      "uncertainty": "source_unspecified",
      "resolution": null,
      "anchors": [
        {
          "line_start": 91,
          "line_end": 91,
          "support": "b is extracted by fitting the kinematic model to velocity profiles after removing plug flow."
        },
        {
          "line_start": 93,
          "line_end": 93,
          "support": "A value of b/d=4.5 is reported for the most crystalline case."
        }
      ]
    },
    {
      "name": "time_averaged_hexatic_order",
      "definition": "Local time-averaged magnitude of the hexatic order parameter <|psi_6|>_t, computed as an Eulerian field.",
      "unit": "dimensionless",
      "statistic": "Time-averaged magnitude of the hexatic order parameter over the steady-state discharge.",
      "uncertainty": "source_unspecified",
      "resolution": null,
      "anchors": [
        {
          "line_start": 106,
          "line_end": 108,
          "support": "The local time-averaged magnitude <|psi_6|>_t is computed as an Eulerian field."
        }
      ]
    }
  ],
  "claims": [
    {
      "claim_id": "b_psi6_linear_correlation",
      "statement": "The diffusion length b/d is linearly correlated with the time-averaged hexatic order parameter <|psi_6|>_t with slope 4.8 and correlation coefficient r=0.942 over the range y/d in [10,70].",
      "quantitative_form": "b/d = 4.8 * <|psi_6|>_t",
      "oracle_outputs": {
        "diffusion_length_b_over_d": {
          "op": "multiply",
          "args": [
            {
              "param": "b_psi6_correlation_slope"
            },
            {
              "var": "time_averaged_hexatic_order"
            }
          ]
        }
      },
      "mechanism_ids": [
        "b_psi6_correlation"
      ],
      "control_names": [
        "time_averaged_hexatic_order"
      ],
      "control_domains": [
        {
          "control_name": "time_averaged_hexatic_order",
          "domain_kind": "continuous_interval",
          "minimum": 0.4,
          "maximum": 0.75,
          "allowed_values": [],
          "domain_statement": "The paper reports <|psi_6|>_t values ranging from 0.4 to 0.55 in high-velocity regions and up to 0.75 in the fully crystalline case (f=0).",
          "anchors": [
            {
              "line_start": 108,
              "line_end": 108,
              "support": "Text states <|psi_6|>_t ranges between 0.4 and 0.55 in high-velocity regions and can reach 0.75 in the fully crystalline case."
            }
          ]
        }
      ],
      "readout_names": [
        "diffusion_length_b_over_d"
      ],
      "fixed_condition_ids": [
        "silo_geometry",
        "particle_sizes",
        "plug_flow_removed"
      ],
      "applicability": "The correlation is reported for the range y/d in [10,70] and for the mixing fractions studied (f in [0,1]). The linear fit is shown in Figure 6.",
      "statistical_basis": "Correlation coefficient r=0.942 reported; slope 4.8 from a line fit. No uncertainty on slope or intercept provided.",
      "uncertainty": "source_unspecified",
      "depends_on": [],
      "anchors": [
        {
          "line_start": 115,
          "line_end": 115,
          "support": "Caption reports correlation r=0.942 and slope 4.8 for the line in the figure."
        }
      ]
    }
  ],
  "source_ambiguities": [
    {
      "ambiguity_id": "slope_uncertainty_unspecified",
      "statement": "The paper reports the slope of the correlation line as 4.8 and the correlation coefficient r=0.942, but does not specify the uncertainty on the slope or whether an intercept was included in the fit.",
      "claim_ids": [
        "b_psi6_linear_correlation"
      ],
      "mechanism_ids": [
        "b_psi6_correlation"
      ],
      "control_names": [
        "time_averaged_hexatic_order"
      ],
      "readout_names": [
        "diffusion_length_b_over_d"
      ],
      "fixed_condition_ids": [],
      "anchors": [
        {
          "line_start": 115,
          "line_end": 115,
          "support": "Caption states slope 4.8 and r=0.942 without uncertainty."
        }
      ]
    }
  ]
}
